css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; }
.dcx a{ color: #0E8C46; text-decoration: none; }
.dcx a:hover{ color: #0B6B3F; }
.dcx :focus-visible{ outline: 2px solid #2FD97F; outline-offset: 3px; }
@media (max-width: 1100px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-hero],.dcx [data-intro],.dcx [data-learn],.dcx [data-cta],.dcx [data-foot]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-steps]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-res]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-spacer]{ display: none !important; }
.dcx [data-slotbg]{ opacity: .35; }
.dcx [data-h1]{ font-size: 48px !important; }
}
@media (max-width: 640px){.dcx [data-steps],.dcx [data-res],.dcx [data-videos]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-h1]{ font-size: 38px !important; }
.dcx [data-h2]{ font-size: 28px !important; }
.dcx [data-pad]{ padding-left: 20px !important; padding-right: 20px !important; }
}
